import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next(), p = next();
        int n = s.length(), m = p.length();
        if (m > n) {
            System.out.println(-1);
            return;
        }
        // Letter counts of the pattern and of the current window of length m.
        int[] want = new int[26], have = new int[26];
        for (int i = 0; i < m; i++) want[p.charAt(i) - 'a']++;
        for (int i = 0; i < m; i++) have[s.charAt(i) - 'a']++;
        for (int i = 0; i + m <= n; i++) {
            if (Arrays.equals(have, want)) {
                System.out.println(i);
                return;
            }
            if (i + m < n) {
                have[s.charAt(i) - 'a']--;
                have[s.charAt(i + m) - 'a']++;
            }
        }
        System.out.println(-1);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s, p := token(), token()
	n, m := len(s), len(p)
	if m > n {
		fmt.Println(-1)
		return
	}
	// Letter counts of the pattern and of the current window of length m.
	var want, have [26]int
	for _, c := range p {
		want[c-'a']++
	}
	for _, c := range s[:m] {
		have[c-'a']++
	}
	for i := 0; i+m <= n; i++ {
		if have == want {
			fmt.Println(i)
			return
		}
		if i+m < n {
			have[s[i]-'a']--
			have[s[i+m]-'a']++
		}
	}
	fmt.Println(-1)
}
